export function resolveForgeExerciseVideo(
  exerciseName: string | null | undefined
): string | null {
  if (!exerciseName) return null
  const rawLower = exerciseName.toLowerCase().trim()
  if (VERIFIED_FORGE_EXERCISE_VIDEOS[rawLower]) {
    return VERIFIED_FORGE_EXERCISE_VIDEOS[rawLower]
  }

  // First check with parenthetical modifiers preserved (e.g. "(Supinated)", "(Close-Grip)")
  const withModifiers = rawLower
    .replace(/^nasm\s*edge\s*[:\-]\s*/i, '')
    .replace(/^nasm\s*[:\-]\s*/i, '')
    .replace(/\s*\|\s*nasm(\s*edge)?$/i, '')
    .replace(/\s*-\s*nasm(\s*edge)?$/i, '')
    .replace(/[-_&/()[\]]+/g, ' ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()

  if (VERIFIED_FORGE_EXERCISE_VIDEOS[withModifiers]) {
    return VERIFIED_FORGE_EXERCISE_VIDEOS[withModifiers]
  }

  if (EXERCISE_ALIAS_MAP[withModifiers] && VERIFIED_FORGE_EXERCISE_VIDEOS[EXERCISE_ALIAS_MAP[withModifiers]]) {
    return VERIFIED_FORGE_EXERCISE_VIDEOS[EXERCISE_ALIAS_MAP[withModifiers]]
  }

  const cleaned = rawLower
    .replace(/^nasm\s*edge\s*[:\-]\s*/i, '')
    .replace(/^nasm\s*[:\-]\s*/i, '')
    .replace(/\s*\|\s*nasm(\s*edge)?$/i, '')
    .replace(/\s*-\s*nasm(\s*edge)?$/i, '')
    .replace(/\([^)]*\)/g, ' ')
    .replace(/\[[^\]]*\]/g, ' ')
    .replace(/phase\s*\d+/gi, ' ')
    .replace(/strength\s*\d+[a-z]?/gi, ' ')
    .replace(/stability\s*\d+[a-z]?/gi, ' ')
    .replace(/power\s*\d+[a-z]?/gi, ' ')
    .replace(/[-_&/]+/g, ' ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()

  if (VERIFIED_FORGE_EXERCISE_VIDEOS[cleaned]) {
    return VERIFIED_FORGE_EXERCISE_VIDEOS[cleaned]
  }

  if (EXERCISE_ALIAS_MAP[cleaned] && VERIFIED_FORGE_EXERCISE_VIDEOS[EXERCISE_ALIAS_MAP[cleaned]]) {
    return VERIFIED_FORGE_EXERCISE_VIDEOS[EXERCISE_ALIAS_MAP[cleaned]]
  }

  return null
}

